# إصلاحُ شائبةِ رقمٍ في 25 (سبعٌ وسبعون→ثلاثٌ وسبعون لا؛ الفاتورةُ 72 ساعة)
for i, row in enumerate(D18):
    if row[0] == 25:
        l = list(row[5])
        l[3] = ("Rückerstattung plus 10-Euro-Gutschein — gutgeschrieben binnen 72 Stunden.", "يُرَدُّ المبلغُ وتُهْدَى قسيمةُ عشرةِ يوروهاتٍ خلالَ اثنتينِ وسبعينَ ساعة.")
        q = list(row[6]); q[1] = ("Wie schnell?", "binnen 72 Stunden", "ein Monat", "sofort", 0, "اثنتانِ وسبعونَ ساعةً — لا تأخيرَ بعدها.")
        D18[i] = (row[0], row[1], row[2], row[3], row[4], l, q, row[7])
        break
for (n, td, ta, A, B, lines, qs, dic) in D18:
    assert len(lines) >= 7, n
    for de, ar in lines:
        assert ARc.search(ar) and not CJK.search(ar) and de.strip() and not ARc.search(de) and not CJK.search(de), (n, de[:36])
    assert len(qs) == 3, n
    for (p, o1, o2, o3, ai, ex) in qs:
        assert len({o1, o2, o3}) == 3 and ai in (0, 1, 2) and ARc.search(ex), (n, p)
    all_de = [x[0] for x in lines]
    for d in dic:
        assert d in all_de, (n, d[:36])
